// =========================================================================
// EDIT YOUR HUGGING FACE TOKEN HERE
// =========================================================================
// Paste your token between the quotes below. Get a free one at:
//   https://huggingface.co/settings/tokens
//
// This single value is used everywhere a Hugging Face token is needed in
// this workflow:
//   1. Authenticating this workflow's own Hugging Face API calls (model
//      search, model info, dataset search, dataset info) — optional, works
//      fine blank too, just with lower rate limits / no gated-model access.
//   2. Auto-filling the HF_TOKEN login cell in every notebook this workflow
//      generates — optional; if blank, the generated notebook just asks
//      whoever runs it to paste their own token in instead.
//
// Leave it as "" (blank) if you don't want either behavior.
//
// NOTE: if you fill this in and plan to share/commit this workflow file
// (e.g. on GitHub), remember your token will be saved in plain text right
// here — keep a blank copy for anything public.
// =========================================================================
const HF_TOKEN = "";

return [{ json: { ...$json, hf_token: HF_TOKEN } }];

// ---------------------------------------------------------------------------
// Build Model Dropdown
// ---------------------------------------------------------------------------
// Turns the Hugging Face model search results into the dynamic dropdown
// shown on Page 2. Falls back to a small curated list if the API call
// failed, returned nothing (bad search term), or the account is rate
// limited — the form must never come back empty.
// ---------------------------------------------------------------------------

const page1 = $('Step 1 – Search Base Models').first().json;

// Defensive against both possible HTTP Request node output shapes: a single
// item whose json IS the array, or the array auto-split into one item per
// element (n8n's behavior here varies by version/settings).
function flattenAll(items) {
  const out = [];
  for (const it of items) {
    const j = it.json;
    if (Array.isArray(j)) out.push(...j);
    else if (j !== undefined && j !== null) out.push(j);
  }
  return out;
}

let results = [];
try {
  results = flattenAll($input.all());
} catch (e) {
  results = [];
}

// Curated fallback — small, well-known instruction/chat models that work
// well on a free-tier Colab GPU, spanning a range of sizes.
const CURATED_FALLBACK = [
  "Qwen/Qwen2.5-1.5B-Instruct",
  "Qwen/Qwen2.5-3B-Instruct",
  "meta-llama/Llama-3.2-1B-Instruct",
  "meta-llama/Llama-3.2-3B-Instruct",
  "meta-llama/Llama-3.1-8B-Instruct",
  "mistralai/Mistral-7B-Instruct-v0.3",
  "google/gemma-2-2b-it",
  "microsoft/Phi-3-mini-4k-instruct",
  "TinyLlama/TinyLlama-1.1B-Chat-v1.0",
  "HuggingFaceH4/zephyr-7b-beta",
];

// --- best-effort size (in billions of params) parsed from the repo id -----
function parseSizeB(id) {
  const m = id.match(/(\d+(?:\.\d+)?)\s*[bB](?![a-zA-Z])/);
  return m ? parseFloat(m[1]) : null;
}

const sizePref = (page1.model_size || "Any").toLowerCase();
function withinSizePref(id) {
  const size = parseSizeB(id);
  if (size === null) return true; // unknown size — don't exclude it
  if (sizePref.startsWith("small")) return size <= 3;
  if (sizePref.startsWith("medium")) return size > 3 && size <= 8;
  if (sizePref.startsWith("large")) return size > 8;
  return true; // "Any"
}

let modelIds = results
  .map(r => r.id || r.modelId)
  .filter(Boolean)
  .filter(withinSizePref);

// De-dupe while preserving the API's relevance/downloads ordering.
modelIds = [...new Set(modelIds)];

let usedFallback = false;
if (modelIds.length === 0) {
  modelIds = CURATED_FALLBACK.filter(withinSizePref);
  if (modelIds.length === 0) modelIds = CURATED_FALLBACK;
  usedFallback = true;
}

// Cap the dropdown to a reasonable length.
modelIds = modelIds.slice(0, 40);

const summaryHtml = usedFallback
  ? `<p>We couldn't fetch a live model list from Hugging Face (bad search term, network hiccup, or rate limit) — showing a curated starter list instead. You can still type any model id below.</p>`
  : `<p>Showing the top ${modelIds.length} Hugging Face models` +
    (page1.model_search ? ` matching "<b>${page1.model_search}</b>"` : ` by downloads`) +
    `. Pick one, or type a custom repo id below to override it.</p>`;

const formFieldsPage2 = [
  { fieldLabel: "Base Model", fieldType: "html", html: `<h3>Choose a Base Model</h3>${summaryHtml}` },
  {
    fieldLabel: "Base model (from Hugging Face)",
    fieldName: "MODEL_NAME_SELECT",
    fieldType: "dropdown",
    requiredField: true,
    fieldOptions: { values: modelIds.map(id => ({ option: id })) },
  },
  {
    fieldLabel: "...or enter a custom Hugging Face model id (overrides the dropdown)",
    fieldName: "MODEL_NAME_CUSTOM",
    fieldType: "text",
    requiredField: false,
    placeholder: "e.g. mistralai/Mistral-7B-v0.1",
  },
];

return [
  {
    json: {
      hf_username: page1.hf_username || "",
      // Kept as a fallback so "Resolve Model Choice" can self-heal instead of
      // hard-failing if the dropdown's selection ever fails to reach it.
      firstModelOption: modelIds[0] || "Qwen/Qwen2.5-1.5B-Instruct",
      formFieldsPage2,
    },
  },
];

// ---------------------------------------------------------------------------
// Resolve Model Choice
// ---------------------------------------------------------------------------
// The custom text field always wins over the dropdown when both are filled.
// If BOTH somehow arrive empty (e.g. a form-rendering quirk swallowed the
// dropdown's selection), fall back to the first option that was offered
// rather than crashing the whole run — and surface a clear note about it.
// ---------------------------------------------------------------------------

const page2 = $json;
const carried = $('Build Model Dropdown').first().json;

const custom = (page2.MODEL_NAME_CUSTOM || "").trim();
const selected = (page2.MODEL_NAME_SELECT || "").trim();
const fallback = carried.firstModelOption || "Qwen/Qwen2.5-1.5B-Instruct";

let MODEL_NAME = custom || selected;
let usedFallback = false;
if (!MODEL_NAME) {
  MODEL_NAME = fallback;
  usedFallback = true;
}

return [
  {
    json: {
      hf_username: carried.hf_username || "",
      MODEL_NAME,
      modelChoiceUsedFallback: usedFallback,
      // Debug aid: if this keeps happening, check these raw values to see
      // whether the form is submitting under different field names.
      _debugPage2Keys: Object.keys(page2),
    },
  },
];

// ---------------------------------------------------------------------------
// Build Dataset Search Params
// ---------------------------------------------------------------------------
// Uses the chosen model's Hugging Face metadata to pick a sensible dataset
// search: the model's declared task (almost always "text-generation" for a
// causal LM) plus a "family" keyword taken from the model id itself (e.g.
// "qwen", "llama", "mistral") so family-specific instruction/chat datasets
// surface near the top of the next page's dropdown.
// ---------------------------------------------------------------------------

const resolved = $('Resolve Model Choice').first().json;
let modelInfo = {};
try { modelInfo = $input.first().json || {}; } catch (e) { modelInfo = {}; }

const pipelineTag = modelInfo.pipeline_tag || "text-generation";
const isGated = !!modelInfo.gated;
const modelType = (modelInfo.config && modelInfo.config.model_type) || null;
const architectures = (modelInfo.config && modelInfo.config.architectures) || [];
const paramCount = (modelInfo.safetensors && modelInfo.safetensors.total) || null;
const maxPositions = (modelInfo.config && modelInfo.config.max_position_embeddings) || null;

// First path segment after the org (e.g. "Qwen/Qwen2.5-1.5B-Instruct" -> "Qwen2.5-1.5B-Instruct"),
// stripped down to just the leading family word (letters only).
const repoTail = resolved.MODEL_NAME.split("/").pop() || "";
const familyMatch = repoTail.match(/^[A-Za-z]+/);
const familyKeyword = familyMatch ? familyMatch[0].toLowerCase() : "";

return [
  {
    json: {
      hf_username: resolved.hf_username || "",
      MODEL_NAME: resolved.MODEL_NAME,
      pipelineTag,
      familyKeyword,
      modelType,
      architectures,
      paramCount,
      maxPositions,
      isGated,
    },
  },
];

// ---------------------------------------------------------------------------
// Build Dataset Dropdown
// ---------------------------------------------------------------------------
// Runs after the "Join Dataset Searches" Merge node, which waits for BOTH
// the family-scoped and task-scoped Hugging Face dataset searches to finish
// (Merge, mode "append") and outputs family results first, task results
// second — so family-relevant datasets float to the top of the dropdown.
//
// Defensive against both possible HTTP Request node output shapes: a
// single item whose json IS the array, or the array auto-split into one
// item per element.
// ---------------------------------------------------------------------------

const ctx = $('Build Dataset Search Params').first().json;

function flattenAll(items) {
  const out = [];
  for (const it of items) {
    const j = it.json;
    if (Array.isArray(j)) out.push(...j);
    else if (j !== undefined && j !== null) out.push(j);
  }
  return out;
}

let merged_raw = [];
try {
  merged_raw = flattenAll($input.all());
} catch (e) {
  merged_raw = [];
}

const CURATED_FALLBACK = [
  "mlabonne/guanaco-llama2-1k",
  "tatsu-lab/alpaca",
  "yahma/alpaca-cleaned",
  "timdettmers/openassistant-guanaco",
  "databricks/databricks-dolly-15k",
  "HuggingFaceH4/ultrachat_200k",
  "OpenAssistant/oasst1",
];

function idOf(d) {
  return (d && (d.id || d.datasetId || d._id)) || null;
}

let ids = merged_raw.map(idOf).filter(Boolean);
let merged = [...new Set(ids)];

let usedFallback = false;
if (merged.length === 0) {
  merged = CURATED_FALLBACK;
  usedFallback = true;
}

merged = merged.slice(0, 40);

const summaryHtml = usedFallback
  ? `<p>We couldn't fetch a live dataset list from Hugging Face — showing a curated starter list of popular instruction/chat datasets instead. You can still type any dataset id below.</p>`
  : `<p>Datasets related to <b>${ctx.MODEL_NAME}</b>` +
    (ctx.familyKeyword ? ` (family: "${ctx.familyKeyword}")` : "") +
    ` and its task ("${ctx.pipelineTag}"), ranked by relevance then downloads. Pick one, or type a custom dataset id below to override it.</p>`;

const formFieldsPage3 = [
  { fieldLabel: "Training Dataset", fieldType: "html", html: `<h3>Choose a Training Dataset</h3>${summaryHtml}` },
  {
    fieldLabel: "Training dataset (from Hugging Face)",
    fieldName: "DATASET_NAME_SELECT",
    fieldType: "dropdown",
    requiredField: true,
    fieldOptions: { values: merged.map(id => ({ option: id })) },
  },
  {
    fieldLabel: "...or enter a custom Hugging Face dataset id (overrides the dropdown)",
    fieldName: "DATASET_NAME_CUSTOM",
    fieldType: "text",
    requiredField: false,
    placeholder: "e.g. my-org/my-instruction-dataset",
  },
];

return [
  {
    json: {
      hf_username: ctx.hf_username || "",
      MODEL_NAME: ctx.MODEL_NAME,
      pipelineTag: ctx.pipelineTag,
      modelType: ctx.modelType,
      architectures: ctx.architectures,
      paramCount: ctx.paramCount,
      maxPositions: ctx.maxPositions,
      isGated: ctx.isGated,
      firstDatasetOption: merged[0] || "mlabonne/guanaco-llama2-1k",
      formFieldsPage3,
    },
  },
];

// ---------------------------------------------------------------------------
// Resolve Dataset Choice
// ---------------------------------------------------------------------------
// Same self-healing pattern as "Resolve Model Choice" — see that node for
// the rationale.
// ---------------------------------------------------------------------------

const page3 = $json;
const carried = $('Build Dataset Dropdown').first().json;

const custom = (page3.DATASET_NAME_CUSTOM || "").trim();
const selected = (page3.DATASET_NAME_SELECT || "").trim();
const fallback = carried.firstDatasetOption || "mlabonne/guanaco-llama2-1k";

let DATASET_NAME = custom || selected;
let usedFallback = false;
if (!DATASET_NAME) {
  DATASET_NAME = fallback;
  usedFallback = true;
}

return [
  {
    json: {
      hf_username: carried.hf_username || "",
      MODEL_NAME: carried.MODEL_NAME,
      pipelineTag: carried.pipelineTag,
      modelType: carried.modelType,
      architectures: carried.architectures,
      paramCount: carried.paramCount,
      maxPositions: carried.maxPositions,
      isGated: carried.isGated,
      DATASET_NAME,
      datasetChoiceUsedFallback: usedFallback,
      _debugPage3Keys: Object.keys(page3),
    },
  },
];

// ---------------------------------------------------------------------------
// Derive Recommendations
// ---------------------------------------------------------------------------
// Turns the chosen model's Hugging Face metadata (and, if readable, the
// dataset's column names) into concrete recommended defaults. These are
// shown as placeholder text on Page 4 — a blank field falls back to the
// recommendation in "Fill Notebook Template"; typing a value overrides it.
// ---------------------------------------------------------------------------

const ctx = $('Resolve Dataset Choice').first().json;

let datasetInfo = {};
try { datasetInfo = $input.first().json || {}; } catch (e) { datasetInfo = {}; }

// --- 1. Recommended LoRA target modules, by architecture family -----------
const LORA_TARGETS_BY_TYPE = {
  llama: ["q_proj", "k_proj", "v_proj", "o_proj"],
  mistral: ["q_proj", "k_proj", "v_proj", "o_proj"],
  mixtral: ["q_proj", "k_proj", "v_proj", "o_proj"],
  qwen2: ["q_proj", "k_proj", "v_proj", "o_proj"],
  qwen2_moe: ["q_proj", "k_proj", "v_proj", "o_proj"],
  qwen3: ["q_proj", "k_proj", "v_proj", "o_proj"],
  gemma: ["q_proj", "k_proj", "v_proj", "o_proj"],
  gemma2: ["q_proj", "k_proj", "v_proj", "o_proj"],
  gemma3: ["q_proj", "k_proj", "v_proj", "o_proj"],
  cohere: ["q_proj", "k_proj", "v_proj", "o_proj"],
  stablelm: ["q_proj", "k_proj", "v_proj", "o_proj"],
  starcoder2: ["q_proj", "k_proj", "v_proj", "o_proj"],
  phi3: ["qkv_proj", "o_proj"],
  phi: ["q_proj", "k_proj", "v_proj", "dense"],
  gpt_neox: ["query_key_value", "dense"],
  gpt2: ["c_attn", "c_proj"],
  bloom: ["query_key_value", "dense"],
  falcon: ["query_key_value", "dense"],
  mpt: ["Wqkv", "out_proj"],
};
const DEFAULT_LORA_TARGETS = ["q_proj", "k_proj", "v_proj", "o_proj"];
const recommendedLoraTargetsArr = ctx.modelType && LORA_TARGETS_BY_TYPE[ctx.modelType]
  ? LORA_TARGETS_BY_TYPE[ctx.modelType]
  : DEFAULT_LORA_TARGETS;
const recommendedLoraTargets = recommendedLoraTargetsArr.join(",");

// --- 2. Recommended max sequence length ------------------------------------
const FREE_TIER_SEQ_CAP = 2048;
const recommendedMaxSeqLength = ctx.maxPositions
  ? Math.max(256, Math.min(ctx.maxPositions, FREE_TIER_SEQ_CAP))
  : 1024;

// --- 3. Recommended 4-bit (QLoRA) loading -----------------------------------
const PARAM_COUNT_4BIT_THRESHOLD = 1_500_000_000;
const recommendedUse4bit = (!ctx.paramCount || ctx.paramCount > PARAM_COUNT_4BIT_THRESHOLD) ? "Yes" : "No";

// --- 4. Gated-model warning --------------------------------------------------
const gatedNote = ctx.isGated
  ? "This model is GATED. Visit its page on huggingface.co, accept the license, and make sure the Hugging Face token you supplied on Step 1 has read access."
  : "This model is not gated — no special access required.";

// --- 5. Detect the dataset's text column and available splits ---------------
let detectedColumns = [];
let detectedSplits = [];
try {
  const infoByConfig = datasetInfo.dataset_info || {};
  const firstConfigKey = Object.keys(infoByConfig)[0];
  if (firstConfigKey && infoByConfig[firstConfigKey].features) {
    detectedColumns = Object.keys(infoByConfig[firstConfigKey].features);
  }
  if (firstConfigKey && infoByConfig[firstConfigKey].splits) {
    detectedSplits = Object.keys(infoByConfig[firstConfigKey].splits);
  }
} catch (e) { /* leave both empty; validation node falls back sensibly */ }
const hasTextColumn = detectedColumns.includes("text");
const recommendedDatasetTextField = hasTextColumn ? "text" : (detectedColumns[0] || "text");
const recommendedDatasetSplit = detectedSplits.includes("train") ? "train" : (detectedSplits[0] || "train");
const datasetColumnsNote = detectedColumns.length
  ? (hasTextColumn
      ? `Detected columns: ${detectedColumns.join(", ")} — a "text" column already exists.`
      : `Detected columns: ${detectedColumns.join(", ")} — no "text" column found, you'll likely need the formatting_func in Section 4 of the notebook.`)
  : "Could not read the dataset's columns automatically — check Section 4 of the notebook.";
const datasetSplitNote = detectedSplits.length
  ? `Detected splits: ${detectedSplits.join(", ")} — using "${recommendedDatasetSplit}".`
  : `Could not detect this dataset's splits automatically — defaulting to "train"; check the dataset's page on huggingface.co if the notebook's dataset-loading cell fails.`;

// --- 6. Recommended Hub repo ids / names -------------------------------------
const hfUsername = ctx.hf_username || "your-username";
const modelSlug = (ctx.MODEL_NAME || "my-model").split("/").pop();
const recommendedHubRepoId = `${hfUsername}/${modelSlug}-finetuned`;
const recommendedDeployRepoId = `${hfUsername}/${modelSlug}-finetuned-merged`;
const recommendedSpaceName = `${modelSlug}-demo`.toLowerCase().replace(/[^a-z0-9-]/g, "-");

const fallbackWarningHtml = (ctx.modelChoiceUsedFallback || ctx.datasetChoiceUsedFallback)
  ? `<p style="color:#b45309"><b>⚠ Heads up:</b> ` +
    [
      ctx.modelChoiceUsedFallback ? "no base model selection was received, so a default was used" : null,
      ctx.datasetChoiceUsedFallback ? "no dataset selection was received, so a default was used" : null,
    ].filter(Boolean).join(" and ") +
    `. Double-check <code>MODEL_NAME</code>/<code>DATASET_NAME</code> in the generated notebook's config cell before running it, ` +
    `and consider using the "...enter a custom id" text box instead of the dropdown next time.</p>`
  : "";

const summaryHtml =
  fallbackWarningHtml +
  `<h3>Detected settings for <code>${ctx.MODEL_NAME}</code> + <code>${ctx.DATASET_NAME}</code></h3>` +
  `<ul>` +
  `<li><b>Architecture:</b> ${ctx.modelType || "unknown"} (${(ctx.architectures || []).join(", ") || "n/a"})</li>` +
  `<li><b>Recommended LoRA targets:</b> ${recommendedLoraTargets}</li>` +
  `<li><b>Recommended max sequence length:</b> ${recommendedMaxSeqLength}</li>` +
  `<li><b>Recommended 4-bit loading:</b> ${recommendedUse4bit}${ctx.paramCount ? ` (~${(ctx.paramCount / 1e9).toFixed(1)}B params)` : " (parameter count unknown)"}</li>` +
  `<li><b>Gating:</b> ${gatedNote}</li>` +
  `<li><b>Dataset columns:</b> ${datasetColumnsNote}</li>` +
  `<li><b>Dataset split:</b> ${datasetSplitNote}</li>` +
  `</ul>` +
  `<p>Every field below is pre-filled with a recommendation as its placeholder — leave a field blank to use it, or type your own value to override it.</p>`;

const formFieldsPage4 = [
  { fieldLabel: "Detected Settings", fieldType: "html", html: summaryHtml },

  { fieldLabel: "1. Dataset & Sequence Length", fieldType: "html", html: "<h3>1. Dataset &amp; Sequence Length</h3>" },
  { fieldLabel: "Dataset text field name", fieldName: "DATASET_TEXT_FIELD", fieldType: "text", placeholder: recommendedDatasetTextField },
  { fieldLabel: "Output directory", fieldName: "OUTPUT_DIR", fieldType: "text", placeholder: "./knatware-finetuned-model" },
  { fieldLabel: "Max sequence length", fieldName: "MAX_SEQ_LENGTH", fieldType: "number", placeholder: String(recommendedMaxSeqLength) },
  { fieldLabel: "Load in 4-bit (QLoRA)?", fieldName: "USE_4BIT", fieldType: "dropdown",
    fieldOptions: { values: [{ option: "Yes" }, { option: "No" }] }, placeholder: recommendedUse4bit },

  { fieldLabel: "2. LoRA Hyperparameters", fieldType: "html", html: "<h3>2. LoRA Hyperparameters</h3>" },
  { fieldLabel: "LoRA rank (r)", fieldName: "LORA_R", fieldType: "number", placeholder: "16" },
  { fieldLabel: "LoRA alpha", fieldName: "LORA_ALPHA", fieldType: "number", placeholder: "32" },
  { fieldLabel: "LoRA dropout", fieldName: "LORA_DROPOUT", fieldType: "number", placeholder: "0.05" },
  { fieldLabel: "LoRA target modules (comma-separated)", fieldName: "LORA_TARGET_MODULES", fieldType: "text", placeholder: recommendedLoraTargets },

  { fieldLabel: "3. Training Arguments", fieldType: "html", html: "<h3>3. Training Arguments</h3>" },
  { fieldLabel: "Epochs", fieldName: "NUM_TRAIN_EPOCHS", fieldType: "number", placeholder: "3" },
  { fieldLabel: "Per-device batch size", fieldName: "PER_DEVICE_TRAIN_BATCH_SIZE", fieldType: "number", placeholder: "2" },
  { fieldLabel: "Gradient accumulation steps", fieldName: "GRADIENT_ACCUMULATION_STEPS", fieldType: "number", placeholder: "4" },
  { fieldLabel: "Learning rate", fieldName: "LEARNING_RATE", fieldType: "text", placeholder: "2e-4" },
  { fieldLabel: "LR scheduler type", fieldName: "LR_SCHEDULER_TYPE", fieldType: "dropdown",
    fieldOptions: { values: [{ option: "cosine" }, { option: "linear" }, { option: "constant" }] }, placeholder: "cosine" },

  { fieldLabel: "4. Save & Hugging Face Hub", fieldType: "html", html: "<h3>4. Save &amp; Hugging Face Hub</h3>" },
  { fieldLabel: "Merge adapter into base model?", fieldName: "MERGE_AND_SAVE", fieldType: "dropdown",
    fieldOptions: { values: [{ option: "Yes" }, { option: "No" }] }, placeholder: "No" },
  { fieldLabel: "Push adapter to the Hub?", fieldName: "PUSH_TO_HUB", fieldType: "dropdown",
    fieldOptions: { values: [{ option: "Yes" }, { option: "No" }] }, placeholder: "No" },
  { fieldLabel: "Hub repo id for the adapter", fieldName: "HUB_REPO_ID", fieldType: "text", placeholder: recommendedHubRepoId },

  { fieldLabel: "5. Inference Test", fieldType: "html", html: "<h3>5. Inference Test</h3>" },
  { fieldLabel: "Test prompt", fieldName: "TEST_PROMPT", fieldType: "textarea",
    placeholder: "### Instruction:\nExplain what fine-tuning an LLM means in one paragraph.\n\n### Response:\n" },
  { fieldLabel: "Max new tokens", fieldName: "TEST_MAX_NEW_TOKENS", fieldType: "number", placeholder: "200" },
  { fieldLabel: "Temperature", fieldName: "TEST_TEMPERATURE", fieldType: "number", placeholder: "0.7" },
  { fieldLabel: "Top-p", fieldName: "TEST_TOP_P", fieldType: "number", placeholder: "0.9" },

  { fieldLabel: "6. Deploy to Hugging Face Spaces (free browser demo)", fieldType: "html", html: "<h3>6. Deploy to Hugging Face Spaces</h3>" },
  { fieldLabel: "Hugging Face username", fieldName: "HF_USERNAME", fieldType: "text", placeholder: hfUsername },
  { fieldLabel: "Space name", fieldName: "SPACE_NAME", fieldType: "text", placeholder: recommendedSpaceName },
  { fieldLabel: "Deployed (merged) model repo id", fieldName: "DEPLOY_MODEL_REPO_ID", fieldType: "text", placeholder: recommendedDeployRepoId },
  { fieldLabel: "Space hardware tier", fieldName: "SPACE_HARDWARE", fieldType: "dropdown",
    fieldOptions: { values: [
      { option: "cpu-basic" }, { option: "cpu-upgrade" }, { option: "t4-small" },
      { option: "t4-medium" }, { option: "l4x1" }, { option: "a10g-small" },
    ] }, placeholder: "cpu-basic" },
  { fieldLabel: "Make Space & model public?", fieldName: "SPACE_PUBLIC", fieldType: "dropdown",
    fieldOptions: { values: [{ option: "Yes" }, { option: "No" }] }, placeholder: "Yes" },

  { fieldLabel: "7. Get Your Notebook", fieldType: "html", html: "<h3>7. Get Your Notebook</h3>" },
  { fieldLabel: "Generated notebook file name", fieldName: "NOTEBOOK_FILENAME", fieldType: "text",
    placeholder: "Knatware_LLM_FineTuning_Generated.ipynb" },
  { fieldLabel: "How would you like to receive it?", fieldName: "DELIVERY_METHOD", fieldType: "dropdown",
    requiredField: true,
    fieldOptions: { values: [
      { option: "Download the .ipynb file" },
      { option: "Upload to Google Drive & open in Colab" },
    ] } },
  { fieldLabel: "Google Drive folder ID (optional — only used for the Colab option above)",
    fieldName: "DRIVE_FOLDER_ID", fieldType: "text", requiredField: false,
    placeholder: "leave blank to upload to your Drive's root folder" },
];

return [
  {
    json: {
      MODEL_NAME: ctx.MODEL_NAME,
      DATASET_NAME: ctx.DATASET_NAME,
      recommendedDatasetTextField,
      recommendedDatasetSplit,
      recommendedMaxSeqLength,
      recommendedUse4bit,
      recommendedLoraTargets,
      recommendedHubRepoId,
      recommendedDeployRepoId,
      recommendedSpaceName,
      // Passed forward purely so "Validate & Sanitize Parameters" can check
      // the form's answers against reality instead of trusting them blindly.
      detectedColumns,
      detectedSplits,
      maxPositions: ctx.maxPositions || null,
      modelType: ctx.modelType || null,
      architectures: ctx.architectures || [],
      formFieldsPage4,
    },
  },
];

// ---------------------------------------------------------------------------
// Validate & Sanitize Parameters
// ---------------------------------------------------------------------------
// Takes the raw Step 4 form answers and checks them against reality (the
// dataset's actual columns/splits, the model's actual context window) and
// against basic sanity limits (positive numbers, non-empty lists, valid
// slugs), instead of trusting typed-in values blindly. Anything invalid or
// out of range is silently replaced with a safe value — the goal is that
// whatever this workflow generates actually runs in Colab without errors
// caused by mismatched or malformed parameters.
// ---------------------------------------------------------------------------

const page4 = $json;
const rec = $('Derive Recommendations').first().json;

function toInt(v, fallback, min, max) {
  const n = parseInt(v, 10);
  let result = Number.isFinite(n) ? n : fallback;
  if (min !== undefined) result = Math.max(min, result);
  if (max !== undefined) result = Math.min(max, result);
  return result;
}

function toFloat(v, fallback, min, max) {
  const n = parseFloat(v);
  let result = Number.isFinite(n) ? n : fallback;
  if (min !== undefined) result = Math.max(min, result);
  if (max !== undefined) result = Math.min(max, result);
  return result;
}

function slugifyRepoName(v, fallback) {
  const s = (v || "").toString().trim().toLowerCase().replace(/[^a-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "");
  return s || fallback;
}

// A Hub repo id must be "org-or-user/repo-name" — validate and rebuild it
// from parts instead of trusting the whole string, so a stray space or
// symbol can't produce something the Hub API rejects at push time.
function sanitizeRepoId(v, fallbackUser, fallbackRepo) {
  const raw = (v || "").toString().trim();
  let userPart, repoPart;
  if (raw.includes("/")) {
    const idx = raw.indexOf("/");
    userPart = slugifyRepoName(raw.slice(0, idx), fallbackUser);
    repoPart = slugifyRepoName(raw.slice(idx + 1), fallbackRepo);
  } else {
    userPart = fallbackUser;
    repoPart = slugifyRepoName(raw, fallbackRepo);
  }
  return `${userPart}/${repoPart}`;
}

const warnings = [];

// --- Dataset text field: must be a real column, or training crashes --------
let DATASET_TEXT_FIELD = (page4.DATASET_TEXT_FIELD || "").trim();
const detectedColumns = rec.detectedColumns || [];
if (!DATASET_TEXT_FIELD) {
  DATASET_TEXT_FIELD = rec.recommendedDatasetTextField;
} else if (detectedColumns.length && !detectedColumns.includes(DATASET_TEXT_FIELD)) {
  warnings.push(`DATASET_TEXT_FIELD "${DATASET_TEXT_FIELD}" is not a real column in ${rec.DATASET_NAME} (detected: ${detectedColumns.join(", ")}) — replaced with "${rec.recommendedDatasetTextField}".`);
  DATASET_TEXT_FIELD = rec.recommendedDatasetTextField;
}

// --- Dataset split: must be a real split, or dataset loading crashes -------
// Not a form field at all (auto-detected only) — see Derive Recommendations.
const DATASET_SPLIT = rec.recommendedDatasetSplit || "train";

// --- Max sequence length: clamp to the model's real context window AND to a
//     ceiling that won't blow past free-tier Colab GPU memory regardless of
//     what the model architecturally supports ---------------------------
const FREE_TIER_SEQ_CAP = 2048;
let MAX_SEQ_LENGTH = toInt(page4.MAX_SEQ_LENGTH, rec.recommendedMaxSeqLength || 1024, 16);
const seqCeiling = rec.maxPositions ? Math.min(rec.maxPositions, FREE_TIER_SEQ_CAP) : FREE_TIER_SEQ_CAP;
if (MAX_SEQ_LENGTH > seqCeiling) {
  const reason = (rec.maxPositions && rec.maxPositions < FREE_TIER_SEQ_CAP)
    ? `exceeds ${rec.MODEL_NAME}'s actual context window (${rec.maxPositions})`
    : `is above the safe ceiling for a free-tier Colab GPU (${FREE_TIER_SEQ_CAP}) — a larger value risks a CUDA out-of-memory error during training`;
  warnings.push(`MAX_SEQ_LENGTH ${MAX_SEQ_LENGTH} ${reason} — clamped to ${seqCeiling}.`);
  MAX_SEQ_LENGTH = seqCeiling;
}

// --- LoRA target modules: must be a non-empty list ---------------------------
let loraTargetsArr = (page4.LORA_TARGET_MODULES || "")
  .split(",").map(s => s.trim()).filter(Boolean);
if (loraTargetsArr.length === 0) {
  loraTargetsArr = (rec.recommendedLoraTargets || "q_proj,k_proj,v_proj,o_proj").split(",");
}
const LORA_TARGET_MODULES = loraTargetsArr.join(",");

// --- Numeric hyperparameters: clamp to ranges that won't crash or stall -----
const LORA_R = toInt(page4.LORA_R, 16, 1, 256);
const LORA_ALPHA = toInt(page4.LORA_ALPHA, 32, 1, 512);
const LORA_DROPOUT = toFloat(page4.LORA_DROPOUT, 0.05, 0, 0.9);
const NUM_TRAIN_EPOCHS = toInt(page4.NUM_TRAIN_EPOCHS, 3, 1, 50);
const PER_DEVICE_TRAIN_BATCH_SIZE = toInt(page4.PER_DEVICE_TRAIN_BATCH_SIZE, 2, 1, 128);
const GRADIENT_ACCUMULATION_STEPS = toInt(page4.GRADIENT_ACCUMULATION_STEPS, 4, 1, 128);

let LEARNING_RATE = parseFloat(page4.LEARNING_RATE);
if (!Number.isFinite(LEARNING_RATE) || LEARNING_RATE <= 0) {
  if (page4.LEARNING_RATE) warnings.push(`LEARNING_RATE "${page4.LEARNING_RATE}" is not a valid positive number — replaced with 2e-4.`);
  LEARNING_RATE = 0.0002;
}

const TEST_MAX_NEW_TOKENS = toInt(page4.TEST_MAX_NEW_TOKENS, 200, 1, 2048);
const TEST_TEMPERATURE = toFloat(page4.TEST_TEMPERATURE, 0.7, 0.01, 2.0);
const TEST_TOP_P = toFloat(page4.TEST_TOP_P, 0.9, 0.01, 1.0);

// --- Repo ids / Space name: must be valid Hub-safe slugs --------------------
const hfUsernameFallback = slugifyRepoName(page4.HF_USERNAME, "your-username");
const modelSlug = slugifyRepoName((rec.MODEL_NAME || "my-model").split("/").pop(), "my-model");

const HUB_REPO_ID = sanitizeRepoId(
  page4.HUB_REPO_ID || rec.recommendedHubRepoId,
  hfUsernameFallback, `${modelSlug}-finetuned`
);
const DEPLOY_MODEL_REPO_ID = sanitizeRepoId(
  page4.DEPLOY_MODEL_REPO_ID || rec.recommendedDeployRepoId,
  hfUsernameFallback, `${modelSlug}-finetuned-merged`
);
const SPACE_NAME = slugifyRepoName(page4.SPACE_NAME || rec.recommendedSpaceName, `${modelSlug}-demo`);

// --- Pass everything else through unchanged (already form-constrained via
//     dropdowns, or free text that doesn't affect whether the notebook runs)
return [
  {
    json: {
      ...page4,
      DATASET_TEXT_FIELD,
      DATASET_SPLIT,
      MAX_SEQ_LENGTH,
      LORA_TARGET_MODULES,
      LORA_R,
      LORA_ALPHA,
      LORA_DROPOUT,
      NUM_TRAIN_EPOCHS,
      PER_DEVICE_TRAIN_BATCH_SIZE,
      GRADIENT_ACCUMULATION_STEPS,
      LEARNING_RATE,
      TEST_MAX_NEW_TOKENS,
      TEST_TEMPERATURE,
      TEST_TOP_P,
      HUB_REPO_ID,
      DEPLOY_MODEL_REPO_ID,
      SPACE_NAME,
      validationWarnings: warnings,
    },
  },
];

