const rec = $('Derive Recommendations').first().json;
const hfToken = $('Config (edit token here)').first().json.hf_token || "";

const TEMPLATE = "{\"cells\":[{\"cell_type\":\"markdown\",\"id\":\"bed01408\",\"metadata\":{},\"source\":[\"# 🔧 LLM Fine-Tuning & Hyperparameter Tuning Notebook\\n\",\"\\n\",\"**Product of:** Knatware Technology — **Developed by:** Kayode Okosi, LLM Developer\\n\",\"\\n\",\"---\\n\",\"\\n\",\"> ## ⚠️ THIS IS A TEMPLATE — DO NOT RUN DIRECTLY\\n\",\">\\n\",\"> This notebook contains `{{ PLACEHOLDER }}`-style tokens (e.g. `{{MODEL_NAME}}`,\\n\",\"> `{{LORA_R}}`, `{{HF_USERNAME}}`) in place of real values. It is meant to\\n\",\"> be filled in automatically by the companion **n8n form workflow**\\n\",\"> (`Knatware_LLM_Notebook_Generator.n8n_workflow.json`), which collects\\n\",\"> your parameters through a web form and outputs a ready-to-run `.ipynb`\\n\",\"> with every placeholder replaced.\\n\",\">\\n\",\"> Running this file as-is in Colab will fail, since `{{MODEL_NAME}}` etc.\\n\",\"> are not valid Python. If you want to edit values by hand instead of\\n\",\"> using the form, just find-and-replace every `{{...}}` token below with\\n\",\"> a real value.\\n\",\"---\\n\",\"\\n\",\"This notebook provides a complete, well-commented pipeline for **fine-tuning and\\n\",\"tuning open-source Large Language Models (LLMs)** on Google Colab using\\n\",\"Hugging Face `transformers`, `datasets`, `peft` (LoRA), and `trl`.\\n\",\"\\n\",\"### What this notebook does\\n\",\"1. Installs and configures the environment (GPU check, dependencies).\\n\",\"2. Loads a base model + tokenizer from the Hugging Face Hub.\\n\",\"3. Loads and preprocesses a training dataset.\\n\",\"4. Configures **LoRA** (Low-Rank Adaptation) for efficient fine-tuning.\\n\",\"5. Sets up training / hyperparameter-tuning arguments.\\n\",\"6. Trains the model and logs metrics.\\n\",\"7. Saves and (optionally) merges + pushes the fine-tuned model.\\n\",\"8. Runs a quick inference test on the fine-tuned model.\\n\",\"9. Optionally previews the model in a temporary browser link (Gradio).\\n\",\"10. Deploys the model permanently to a free Hugging Face Space, with a\\n\",\"    stable public URL you can share or embed anywhere.\\n\",\"\\n\",\"### ⚠️ Compulsory parameters\\n\",\"Throughout this notebook, cells that require you to supply a value are marked\\n\",\"with a `# COMPULSORY:` comment. Search for `COMPULSORY` in this notebook to\\n\",\"find every value you must set before running.\\n\",\"\\n\",\"### Recommended Colab runtime\\n\",\"`Runtime > Change runtime type > T4 GPU` (or better, e.g. A100/L4 if available\\n\",\"on Colab Pro) — fine-tuning LLMs requires a GPU.\\n\",\"\\n\",\"---\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"b23b628a\",\"metadata\":{},\"source\":[\"## 1. Environment Setup\\n\",\"\\n\",\"Check the GPU assigned by Colab and install the required libraries.\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"bf00eeff\",\"metadata\":{},\"outputs\":[],\"source\":[\"# Check which GPU Colab has assigned to this runtime.\\n\",\"# If this errors out or shows \\\"no GPU\\\", go to:\\n\",\"#   Runtime > Change runtime type > Hardware accelerator > GPU\\n\",\"!nvidia-smi\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"89455cff\",\"metadata\":{},\"outputs\":[],\"source\":[\"# ------------------------------------------------------------------------\\n\",\"# Install dependencies\\n\",\"# ------------------------------------------------------------------------\\n\",\"# transformers  -> model + tokenizer loading, Trainer API\\n\",\"# datasets      -> loading and preprocessing training data\\n\",\"# accelerate    -> multi-GPU / mixed-precision training backend\\n\",\"# peft          -> Parameter-Efficient Fine-Tuning (LoRA, QLoRA, etc.)\\n\",\"# trl           -> SFTTrainer (Supervised Fine-Tuning Trainer), simplifies the training loop\\n\",\"# bitsandbytes  -> 8-bit / 4-bit quantization (needed for QLoRA on limited-VRAM GPUs)\\n\",\"# evaluate      -> metrics (e.g. accuracy, perplexity) during evaluation\\n\",\"# wandb         -> optional experiment tracking / hyperparameter tuning dashboard\\n\",\"!pip install -q -U transformers datasets accelerate peft trl bitsandbytes evaluate wandb sentencepiece\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"03488613\",\"metadata\":{},\"outputs\":[],\"source\":[\"import os\\n\",\"import torch\\n\",\"import numpy as np\\n\",\"\\n\",\"from datasets import load_dataset\\n\",\"from transformers import (\\n\",\"    AutoTokenizer,\\n\",\"    AutoModelForCausalLM,\\n\",\"    BitsAndBytesConfig,\\n\",\"    TrainingArguments,\\n\",\")\\n\",\"from peft import LoraConfig, get_peft_model, prepare_model_for_kbit_training, PeftModel\\n\",\"from trl import SFTTrainer, SFTConfig\\n\",\"\\n\",\"# Confirm GPU is visible to PyTorch\\n\",\"print(\\\"CUDA available:\\\", torch.cuda.is_available())\\n\",\"if torch.cuda.is_available():\\n\",\"    print(\\\"GPU device:\\\", torch.cuda.get_device_name(0))\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"9cc9075f\",\"metadata\":{},\"source\":[\"## 2. (Optional) Hugging Face & Weights & Biases Login\\n\",\"\\n\",\"* Hugging Face login is required if you are using a **gated model** (e.g. Llama,\\n\",\"  Gemma) or want to **push your fine-tuned model** to the Hub.\\n\",\"* W&B login is optional and only needed if you want live dashboards for\\n\",\"  hyperparameter tuning / experiment tracking.\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"40938daf\",\"metadata\":{},\"outputs\":[],\"source\":[\"from huggingface_hub import login\\n\",\"\\n\",\"# COMPULSORY (only if using a gated model or pushing to the Hub):\\n\",\"# HF_TOKEN below is NOT something you typed into the generator form — it\\n\",\"# comes from the n8n workflow's \\\"Config (edit token here)\\\" node (the first\\n\",\"# code node after the trigger), so the same value is used for every\\n\",\"# notebook this workflow generates. It ships blank by default. To change\\n\",\"# it, edit the HF_TOKEN constant in that node's code, or just replace the\\n\",\"# value below directly and re-run this cell.\\n\",\"# Get a token at https://huggingface.co/settings/tokens\\n\",\"HF_TOKEN = \\\"{{HF_TOKEN}}\\\"\\n\",\"\\n\",\"if HF_TOKEN:\\n\",\"    login(token=HF_TOKEN)\\n\",\"else:\\n\",\"    print(\\\"No Hugging Face token was configured — skipping login. If you need one \\\"\\n\",\"          \\\"(gated model / push to Hub), get one from https://huggingface.co/settings/tokens \\\"\\n\",\"          \\\"and run login(token=\\\\\\\"...\\\\\\\") manually.\\\")\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"93b08658\",\"metadata\":{},\"outputs\":[],\"source\":[\"import wandb\\n\",\"\\n\",\"# OPTIONAL: enables live loss/metric tracking during training and tuning.\\n\",\"# Get a free API key from https://wandb.ai/authorize\\n\",\"# Uncomment to enable:\\n\",\"# wandb.login()\\n\",\"\\n\",\"# If you don't want to use W&B at all, set this environment variable\\n\",\"# so the Trainer doesn't try to log to it:\\n\",\"os.environ[\\\"WANDB_DISABLED\\\"] = \\\"true\\\"\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"c30c4534\",\"metadata\":{},\"source\":[\"## 3. Core Configuration\\n\",\"\\n\",\"Set all the core (compulsory) parameters for this fine-tuning run in one place.\\n\",\"Everything downstream reads from this config block, so this is the main section\\n\",\"you need to edit for your own project.\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"69c1871e\",\"metadata\":{},\"outputs\":[],\"source\":[\"# =============================================================================\\n\",\"# COMPULSORY CONFIGURATION BLOCK\\n\",\"# Edit every value in this cell before running the rest of the notebook.\\n\",\"# =============================================================================\\n\",\"\\n\",\"# COMPULSORY: Base model to fine-tune.\\n\",\"# Must be a valid Hugging Face model repo id (e.g. \\\"meta-llama/Llama-3.2-1B\\\",\\n\",\"# \\\"mistralai/Mistral-7B-v0.1\\\", \\\"google/gemma-2-2b\\\", \\\"Qwen/Qwen2.5-1.5B\\\").\\n\",\"# Smaller models (1B-3B) are recommended for free-tier Colab GPUs.\\n\",\"MODEL_NAME = \\\"{{MODEL_NAME}}\\\"\\n\",\"\\n\",\"# COMPULSORY: Training dataset.\\n\",\"# Must be a valid Hugging Face dataset repo id, OR a local/uploaded file path\\n\",\"# (e.g. \\\"my_data.jsonl\\\") loaded via load_dataset(\\\"json\\\", data_files=...).\\n\",\"DATASET_NAME = \\\"{{DATASET_NAME}}\\\"\\n\",\"\\n\",\"# COMPULSORY: which split of the dataset to train on. Auto-detected from the\\n\",\"# dataset's actual available splits when this notebook was generated (not\\n\",\"# every dataset has a \\\"train\\\" split — some use \\\"training\\\", \\\"default\\\", or\\n\",\"# something else entirely, and loading a split that doesn't exist crashes\\n\",\"# the next cell).\\n\",\"DATASET_SPLIT = \\\"{{DATASET_SPLIT}}\\\"\\n\",\"\\n\",\"# COMPULSORY: Name of the text field in the dataset that SFTTrainer should\\n\",\"# train on. If your dataset has multiple fields (instruction/response, etc.)\\n\",\"# you must format them into a single \\\"text\\\" field first (see Section 4).\\n\",\"DATASET_TEXT_FIELD = \\\"{{DATASET_TEXT_FIELD}}\\\"\\n\",\"\\n\",\"# COMPULSORY: Directory where checkpoints and the final fine-tuned model\\n\",\"# are saved. This will be created automatically if it doesn't exist.\\n\",\"OUTPUT_DIR = \\\"{{OUTPUT_DIR}}\\\"\\n\",\"\\n\",\"# COMPULSORY: Maximum sequence length (in tokens) used for training.\\n\",\"# Longer sequences use more GPU memory. 512-1024 is a safe range for\\n\",\"# free-tier Colab GPUs.\\n\",\"MAX_SEQ_LENGTH = {{MAX_SEQ_LENGTH}}\\n\",\"\\n\",\"# COMPULSORY: Whether to load the base model in 4-bit precision (QLoRA).\\n\",\"# Strongly recommended = True on free Colab GPUs (T4 has only ~15GB VRAM).\\n\",\"USE_4BIT = {{USE_4BIT}}\\n\",\"\\n\",\"print(\\\"Configuration set:\\\")\\n\",\"print(f\\\"  MODEL_NAME          = {MODEL_NAME}\\\")\\n\",\"print(f\\\"  DATASET_NAME         = {DATASET_NAME}\\\")\\n\",\"print(f\\\"  DATASET_SPLIT        = {DATASET_SPLIT}\\\")\\n\",\"print(f\\\"  DATASET_TEXT_FIELD   = {DATASET_TEXT_FIELD}\\\")\\n\",\"print(f\\\"  OUTPUT_DIR           = {OUTPUT_DIR}\\\")\\n\",\"print(f\\\"  MAX_SEQ_LENGTH       = {MAX_SEQ_LENGTH}\\\")\\n\",\"print(f\\\"  USE_4BIT             = {USE_4BIT}\\\")\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"0d0b522a\",\"metadata\":{},\"source\":[\"## 4. Load & Preprocess the Dataset\\n\",\"\\n\",\"Loads the dataset defined above and (if needed) formats it into a single\\n\",\"`text` field that `SFTTrainer` can consume directly.\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"250ce0da\",\"metadata\":{},\"outputs\":[],\"source\":[\"# Load the dataset from the Hugging Face Hub.\\n\",\"# If instead you have your own local file, replace this line with e.g.:\\n\",\"#   dataset = load_dataset(\\\"json\\\", data_files=\\\"my_data.jsonl\\\", split=\\\"train\\\")\\n\",\"#   dataset = load_dataset(\\\"csv\\\", data_files=\\\"my_data.csv\\\", split=\\\"train\\\")\\n\",\"dataset = load_dataset(DATASET_NAME, split=DATASET_SPLIT)\\n\",\"\\n\",\"print(dataset)\\n\",\"print(\\\"\\\\nSample record:\\\")\\n\",\"print(dataset[0])\\n\",\"\\n\",\"# Runtime safety check: confirm DATASET_TEXT_FIELD actually exists as a\\n\",\"# column before spending time loading the model — a mismatch here is one\\n\",\"# of the most common causes of a crash deep inside SFTTrainer, so we fail\\n\",\"# fast with a clear, actionable message instead.\\n\",\"if DATASET_TEXT_FIELD not in dataset.column_names:\\n\",\"    raise ValueError(\\n\",\"        f\\\"DATASET_TEXT_FIELD is set to '{DATASET_TEXT_FIELD}', but the dataset's actual \\\"\\n\",\"        f\\\"columns are: {dataset.column_names}. Either change DATASET_TEXT_FIELD above to \\\"\\n\",\"        f\\\"one of those columns, or define formatting_func in the next cell to combine \\\"\\n\",\"        f\\\"multiple columns into a single training text field.\\\"\\n\",\"    )\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"1c56055f\",\"metadata\":{},\"outputs\":[],\"source\":[\"# ------------------------------------------------------------------------\\n\",\"# OPTIONAL formatting function\\n\",\"# ------------------------------------------------------------------------\\n\",\"# If your dataset does NOT already contain a single \\\"text\\\" column formatted\\n\",\"# as a full prompt/response string, define a formatting function here that\\n\",\"# converts each example into the format your model expects (e.g. chat\\n\",\"# template). SFTTrainer will call this automatically if provided.\\n\",\"#\\n\",\"# Uncomment and adapt this template if your dataset has separate\\n\",\"# \\\"instruction\\\" / \\\"response\\\" (or similar) columns instead of \\\"text\\\":\\n\",\"\\n\",\"# def formatting_func(example):\\n\",\"#     return f\\\"\\\"\\\"### Instruction:\\n\",\"# {example['instruction']}\\n\",\"#\\n\",\"# ### Response:\\n\",\"# {example['response']}\\\"\\\"\\\"\\n\",\"\\n\",\"# If your DATASET_TEXT_FIELD already exists and is fully formatted, you can\\n\",\"# leave formatting_func as None.\\n\",\"formatting_func = None\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"e1d77c9c\",\"metadata\":{},\"source\":[\"## 5. Load Tokenizer & Base Model\\n\",\"\\n\",\"Loads the tokenizer and base model defined in `MODEL_NAME`, optionally in\\n\",\"4-bit precision (QLoRA) to fit on free-tier Colab GPUs.\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"6598e63b\",\"metadata\":{},\"outputs\":[],\"source\":[\"# ------------------------------------------------------------------------\\n\",\"# Tokenizer\\n\",\"# ------------------------------------------------------------------------\\n\",\"tokenizer = AutoTokenizer.from_pretrained(MODEL_NAME, trust_remote_code=True)\\n\",\"\\n\",\"# Most causal LMs don't define a pad token by default; reuse EOS as PAD.\\n\",\"if tokenizer.pad_token is None:\\n\",\"    tokenizer.pad_token = tokenizer.eos_token\\n\",\"\\n\",\"tokenizer.padding_side = \\\"right\\\"  # recommended for causal LM fine-tuning\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"b1752c00\",\"metadata\":{},\"outputs\":[],\"source\":[\"# ------------------------------------------------------------------------\\n\",\"# 4-bit (QLoRA) quantization config\\n\",\"# ------------------------------------------------------------------------\\n\",\"# load_in_4bit             -> loads model weights in 4-bit precision to save VRAM\\n\",\"# bnb_4bit_quant_type       -> \\\"nf4\\\" is the recommended quant type for LLMs\\n\",\"# bnb_4bit_compute_dtype    -> compute dtype used during forward/backward pass\\n\",\"# bnb_4bit_use_double_quant -> further reduces memory via nested quantization\\n\",\"bnb_config = BitsAndBytesConfig(\\n\",\"    load_in_4bit=USE_4BIT,\\n\",\"    bnb_4bit_quant_type=\\\"nf4\\\",\\n\",\"    bnb_4bit_compute_dtype=torch.bfloat16,\\n\",\"    bnb_4bit_use_double_quant=True,\\n\",\")\\n\",\"\\n\",\"# ------------------------------------------------------------------------\\n\",\"# Load the base model\\n\",\"# ------------------------------------------------------------------------\\n\",\"model = AutoModelForCausalLM.from_pretrained(\\n\",\"    MODEL_NAME,\\n\",\"    quantization_config=bnb_config if USE_4BIT else None,\\n\",\"    device_map=\\\"auto\\\",          # automatically place model on available GPU(s)\\n\",\"    trust_remote_code=True,\\n\",\")\\n\",\"\\n\",\"model.config.use_cache = False       # required for gradient checkpointing during training\\n\",\"model.config.pretraining_tp = 1      # disables tensor parallel rank splitting (safe default)\\n\",\"\\n\",\"if USE_4BIT:\\n\",\"    model = prepare_model_for_kbit_training(model)\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"65dedcdb\",\"metadata\":{},\"source\":[\"## 6. Configure LoRA (Parameter-Efficient Fine-Tuning)\\n\",\"\\n\",\"LoRA freezes the base model weights and trains small low-rank \\\"adapter\\\"\\n\",\"matrices instead — this drastically reduces GPU memory and training time\\n\",\"while achieving results close to full fine-tuning.\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"21f05251\",\"metadata\":{},\"outputs\":[],\"source\":[\"# =============================================================================\\n\",\"# COMPULSORY: LoRA hyperparameters\\n\",\"# These are the primary \\\"tuning\\\" knobs for LoRA fine-tuning.\\n\",\"# =============================================================================\\n\",\"\\n\",\"# COMPULSORY: LoRA rank. Controls the size of the trainable adapter matrices.\\n\",\"# Higher = more capacity but more memory/compute. Common values: 8, 16, 32, 64.\\n\",\"LORA_R = {{LORA_R}}\\n\",\"\\n\",\"# COMPULSORY: LoRA scaling factor. Typically set to 2x LORA_R.\\n\",\"LORA_ALPHA = {{LORA_ALPHA}}\\n\",\"\\n\",\"# COMPULSORY: Dropout applied to LoRA layers, helps prevent overfitting.\\n\",\"LORA_DROPOUT = {{LORA_DROPOUT}}\\n\",\"\\n\",\"# COMPULSORY: Which linear layers to attach LoRA adapters to.\\n\",\"# For most decoder-only LLMs, attention projection layers are targeted.\\n\",\"# Adjust based on your model architecture if needed (check model.named_modules()).\\n\",\"LORA_TARGET_MODULES = {{LORA_TARGET_MODULES}}\\n\",\"\\n\",\"# Runtime safety check: keep only target module names that actually exist\\n\",\"# in this model's architecture. A name that doesn't match anything makes\\n\",\"# LoraConfig fail with a fairly cryptic error, so we filter proactively\\n\",\"# and fall back to the model's real linear-layer names if nothing matches.\\n\",\"_all_module_names = {name.split(\\\".\\\")[-1] for name, _ in model.named_modules()}\\n\",\"_valid_targets = [m for m in LORA_TARGET_MODULES if m in _all_module_names]\\n\",\"if not _valid_targets:\\n\",\"    import torch.nn as nn\\n\",\"    print(f\\\"None of {LORA_TARGET_MODULES} were found on this model — falling back to \\\"\\n\",\"          f\\\"auto-detected linear layer names.\\\")\\n\",\"    _valid_targets = sorted({\\n\",\"        name.split(\\\".\\\")[-1] for name, module in model.named_modules()\\n\",\"        if isinstance(module, nn.Linear) and \\\"lm_head\\\" not in name\\n\",\"    })\\n\",\"    print(f\\\"Using: {_valid_targets}\\\")\\n\",\"LORA_TARGET_MODULES = _valid_targets\\n\",\"\\n\",\"lora_config = LoraConfig(\\n\",\"    r=LORA_R,\\n\",\"    lora_alpha=LORA_ALPHA,\\n\",\"    lora_dropout=LORA_DROPOUT,\\n\",\"    target_modules=LORA_TARGET_MODULES,\\n\",\"    bias=\\\"none\\\",\\n\",\"    task_type=\\\"CAUSAL_LM\\\",\\n\",\")\\n\",\"\\n\",\"model = get_peft_model(model, lora_config)\\n\",\"\\n\",\"# Prints how many parameters are actually trainable vs. total —\\n\",\"# with LoRA this is typically <1-2% of total model parameters.\\n\",\"model.print_trainable_parameters()\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"9f09f425\",\"metadata\":{},\"source\":[\"## 7. Training & Hyperparameter-Tuning Arguments\\n\",\"\\n\",\"These are the main hyperparameters you will experiment with when **tuning**\\n\",\"the model. Each compulsory field is commented with its purpose and typical\\n\",\"value range.\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"170f4bc4\",\"metadata\":{},\"outputs\":[],\"source\":[\"# =============================================================================\\n\",\"# COMPULSORY: Training / hyperparameter-tuning configuration\\n\",\"# =============================================================================\\n\",\"training_args = SFTConfig(\\n\",\"\\n\",\"    # COMPULSORY: where checkpoints + logs are written (must match OUTPUT_DIR).\\n\",\"    output_dir=OUTPUT_DIR,\\n\",\"\\n\",\"    # COMPULSORY: number of full passes over the training dataset.\\n\",\"    # 1-3 epochs is typical for instruction fine-tuning to avoid overfitting.\\n\",\"    num_train_epochs={{NUM_TRAIN_EPOCHS}},\\n\",\"\\n\",\"    # COMPULSORY: batch size per GPU device. Reduce if you hit CUDA OOM errors.\\n\",\"    per_device_train_batch_size={{PER_DEVICE_TRAIN_BATCH_SIZE}},\\n\",\"\\n\",\"    # COMPULSORY: number of steps to accumulate gradients before an optimizer\\n\",\"    # step. Effective batch size = per_device_train_batch_size * this value.\\n\",\"    # Use this to simulate a larger batch size on limited VRAM.\\n\",\"    gradient_accumulation_steps={{GRADIENT_ACCUMULATION_STEPS}},\\n\",\"\\n\",\"    # COMPULSORY: optimizer. \\\"paged_adamw_32bit\\\" is memory-efficient and\\n\",\"    # recommended when using 4-bit/8-bit quantized models.\\n\",\"    optim=\\\"paged_adamw_32bit\\\",\\n\",\"\\n\",\"    # COMPULSORY: how often (in steps) to log training metrics.\\n\",\"    logging_steps=10,\\n\",\"\\n\",\"    # COMPULSORY: how often (in steps) to save a checkpoint.\\n\",\"    save_steps=50,\\n\",\"\\n\",\"    # COMPULSORY: learning rate — the single most impactful tuning parameter.\\n\",\"    # Typical LoRA fine-tuning range: 1e-4 to 3e-4.\\n\",\"    learning_rate={{LEARNING_RATE}},\\n\",\"\\n\",\"    # COMPULSORY: max gradient norm for gradient clipping (prevents exploding\\n\",\"    # gradients).\\n\",\"    max_grad_norm=0.3,\\n\",\"\\n\",\"    # COMPULSORY: fraction of total training steps used to linearly warm up\\n\",\"    # the learning rate from 0 to the target learning_rate.\\n\",\"    warmup_ratio=0.03,\\n\",\"\\n\",\"    # COMPULSORY: learning-rate schedule shape after warmup.\\n\",\"    # \\\"cosine\\\" smoothly decays LR to 0; \\\"constant\\\" and \\\"linear\\\" are alternatives.\\n\",\"    lr_scheduler_type=\\\"{{LR_SCHEDULER_TYPE}}\\\",\\n\",\"\\n\",\"    # COMPULSORY: use mixed precision (bf16) if the GPU supports it (A100/T4\\n\",\"    # support bf16; older GPUs may need fp16=True, bf16=False instead).\\n\",\"    bf16=True,\\n\",\"    fp16=False,\\n\",\"\\n\",\"    # COMPULSORY: reduces memory usage by not storing all activations during\\n\",\"    # the forward pass (recomputes them during backward pass instead).\\n\",\"    gradient_checkpointing=True,\\n\",\"\\n\",\"    # COMPULSORY: maximum tokenized sequence length (must match MAX_SEQ_LENGTH).\\n\",\"    max_length=MAX_SEQ_LENGTH,\\n\",\"\\n\",\"    # COMPULSORY: which column in the dataset holds the training text\\n\",\"    # (must match DATASET_TEXT_FIELD).\\n\",\"    dataset_text_field=DATASET_TEXT_FIELD,\\n\",\"\\n\",\"    # Disables external experiment-tracking integrations by default.\\n\",\"    # Set to \\\"wandb\\\" if you logged in above and want live dashboards.\\n\",\"    report_to=\\\"none\\\",\\n\",\")\\n\",\"\\n\",\"print(\\\"Training arguments configured.\\\")\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"e22ac582\",\"metadata\":{},\"source\":[\"## 8. Build the Trainer and Start Fine-Tuning\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"51e59933\",\"metadata\":{},\"outputs\":[],\"source\":[\"trainer = SFTTrainer(\\n\",\"    model=model,\\n\",\"    args=training_args,\\n\",\"    train_dataset=dataset,\\n\",\"    formatting_func=formatting_func,   # None if dataset already has a \\\"text\\\" field\\n\",\"    processing_class=tokenizer,\\n\",\"    peft_config=lora_config,\\n\",\")\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"4119093e\",\"metadata\":{},\"outputs\":[],\"source\":[\"# Start training. This is the long-running cell — progress (loss, learning\\n\",\"# rate, etc.) will print every `logging_steps` steps as configured above.\\n\",\"train_result = trainer.train()\\n\",\"\\n\",\"# Print a short summary of the training run.\\n\",\"print(train_result)\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"0ca97007\",\"metadata\":{},\"source\":[\"## 9. Save the Fine-Tuned Model\\n\",\"\\n\",\"Saves the LoRA adapter weights (small file size) to `OUTPUT_DIR`. To get a\\n\",\"single standalone model (adapter merged into the base weights), run the\\n\",\"optional merge cell afterward.\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"b93bbd0a\",\"metadata\":{},\"outputs\":[],\"source\":[\"# Saves only the LoRA adapter weights + tokenizer (small, a few MB to ~100MB).\\n\",\"trainer.model.save_pretrained(OUTPUT_DIR)\\n\",\"tokenizer.save_pretrained(OUTPUT_DIR)\\n\",\"\\n\",\"print(f\\\"Adapter and tokenizer saved to: {OUTPUT_DIR}\\\")\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"318fa594\",\"metadata\":{},\"outputs\":[],\"source\":[\"# ------------------------------------------------------------------------\\n\",\"# OPTIONAL: Merge LoRA adapter into the base model\\n\",\"# ------------------------------------------------------------------------\\n\",\"# Produces a single, standalone fine-tuned model (same size as the base\\n\",\"# model) that can be loaded without the `peft` library. Useful for\\n\",\"# deployment. Requires enough RAM/VRAM to hold the full-precision model.\\n\",\"\\n\",\"MERGE_AND_SAVE = {{MERGE_AND_SAVE}}  # COMPULSORY: set True if you want a merged full model\\n\",\"\\n\",\"if MERGE_AND_SAVE:\\n\",\"    merged_model = trainer.model.merge_and_unload()\\n\",\"    merged_output_dir = OUTPUT_DIR + \\\"-merged\\\"\\n\",\"    merged_model.save_pretrained(merged_output_dir, safe_serialization=True)\\n\",\"    tokenizer.save_pretrained(merged_output_dir)\\n\",\"    print(f\\\"Merged model saved to: {merged_output_dir}\\\")\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"57f812f9\",\"metadata\":{},\"source\":[\"## 10. (Optional) Push the Fine-Tuned Model to the Hugging Face Hub\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"3f6ff41d\",\"metadata\":{},\"outputs\":[],\"source\":[\"PUSH_TO_HUB = {{PUSH_TO_HUB}}  # COMPULSORY: set True to enable pushing to the Hub\\n\",\"\\n\",\"# COMPULSORY (only if PUSH_TO_HUB=True): your target Hub repo id,\\n\",\"# e.g. \\\"your-username/your-model-name\\\"\\n\",\"HUB_REPO_ID = \\\"{{HUB_REPO_ID}}\\\"\\n\",\"\\n\",\"if PUSH_TO_HUB:\\n\",\"    trainer.model.push_to_hub(HUB_REPO_ID)\\n\",\"    tokenizer.push_to_hub(HUB_REPO_ID)\\n\",\"    print(f\\\"Model pushed to: https://huggingface.co/{HUB_REPO_ID}\\\")\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"5efda838\",\"metadata\":{},\"source\":[\"## 11. Quick Inference Test\\n\",\"\\n\",\"Loads the fine-tuned adapter on top of the base model and generates a sample\\n\",\"response to sanity-check that fine-tuning worked as expected.\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"f8978867\",\"metadata\":{},\"outputs\":[],\"source\":[\"from transformers import pipeline\\n\",\"\\n\",\"# Reload base model + attach the fine-tuned adapter for a clean inference test.\\n\",\"inference_model = AutoModelForCausalLM.from_pretrained(\\n\",\"    MODEL_NAME,\\n\",\"    quantization_config=bnb_config if USE_4BIT else None,\\n\",\"    device_map=\\\"auto\\\",\\n\",\"    trust_remote_code=True,\\n\",\")\\n\",\"inference_model = PeftModel.from_pretrained(inference_model, OUTPUT_DIR)\\n\",\"\\n\",\"generator = pipeline(\\n\",\"    \\\"text-generation\\\",\\n\",\"    model=inference_model,\\n\",\"    tokenizer=tokenizer,\\n\",\")\\n\",\"\\n\",\"# COMPULSORY: edit this prompt to test your fine-tuned model on a relevant example.\\n\",\"TEST_PROMPT = \\\"{{TEST_PROMPT}}\\\"\\n\",\"\\n\",\"output = generator(\\n\",\"    TEST_PROMPT,\\n\",\"    max_new_tokens={{TEST_MAX_NEW_TOKENS}},     # COMPULSORY: max number of new tokens to generate\\n\",\"    do_sample=True,         # COMPULSORY: enables sampling (vs. greedy decoding)\\n\",\"    temperature={{TEST_TEMPERATURE}},        # COMPULSORY: randomness of output; lower = more deterministic\\n\",\"    top_p={{TEST_TOP_P}},               # COMPULSORY: nucleus sampling threshold\\n\",\")\\n\",\"\\n\",\"print(output[0][\\\"generated_text\\\"])\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"0d238712\",\"metadata\":{},\"source\":[\"## 12. (Optional) Simple Hyperparameter Tuning Sweep\\n\",\"\\n\",\"A minimal example of looping over a small grid of hyperparameters (e.g.\\n\",\"learning rate, LoRA rank) to compare training loss across runs. For serious\\n\",\"tuning at scale, consider `optuna` or W&B Sweeps instead.\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"d73d96b4\",\"metadata\":{},\"outputs\":[],\"source\":[\"# OPTIONAL: example grid-search sweep over learning rate.\\n\",\"# Each run trains for a very small number of steps just to compare loss —\\n\",\"# extend `num_train_epochs` / remove `max_steps` for a real sweep.\\n\",\"\\n\",\"RUN_HYPERPARAMETER_SWEEP = False  # set True to run this cell's sweep\\n\",\"\\n\",\"if RUN_HYPERPARAMETER_SWEEP:\\n\",\"    learning_rates_to_try = [1e-4, 2e-4, 3e-4]  # COMPULSORY: values to sweep over\\n\",\"    sweep_results = {}\\n\",\"\\n\",\"    for lr in learning_rates_to_try:\\n\",\"        print(f\\\"\\\\n=== Training with learning_rate={lr} ===\\\")\\n\",\"        sweep_args = SFTConfig(\\n\",\"            output_dir=f\\\"{OUTPUT_DIR}-lr{lr}\\\",\\n\",\"            max_steps=20,                # short run, just for comparison\\n\",\"            per_device_train_batch_size=2,\\n\",\"            gradient_accumulation_steps=4,\\n\",\"            learning_rate=lr,\\n\",\"            logging_steps=5,\\n\",\"            bf16=True,\\n\",\"            gradient_checkpointing=True,\\n\",\"            max_length=MAX_SEQ_LENGTH,\\n\",\"            dataset_text_field=DATASET_TEXT_FIELD,\\n\",\"            report_to=\\\"none\\\",\\n\",\"        )\\n\",\"        sweep_trainer = SFTTrainer(\\n\",\"            model=model,\\n\",\"            args=sweep_args,\\n\",\"            train_dataset=dataset,\\n\",\"            formatting_func=formatting_func,\\n\",\"            processing_class=tokenizer,\\n\",\"            peft_config=lora_config,\\n\",\"        )\\n\",\"        result = sweep_trainer.train()\\n\",\"        sweep_results[lr] = result.training_loss\\n\",\"        print(f\\\"Final training loss for lr={lr}: {result.training_loss}\\\")\\n\",\"\\n\",\"    print(\\\"\\\\nSweep summary:\\\", sweep_results)\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"18d56b48\",\"metadata\":{},\"source\":[\"---\\n\",\"\\n\",\"### Notes\\n\",\"- If you hit `CUDA out of memory`, reduce `per_device_train_batch_size`,\\n\",\"  increase `gradient_accumulation_steps`, lower `MAX_SEQ_LENGTH`, or keep\\n\",\"  `USE_4BIT = True`.\\n\",\"- For larger models (7B+), use Colab Pro/Pro+ with an A100 GPU, or reduce\\n\",\"  `LORA_R` and batch size further.\\n\",\"- Always validate the fine-tuned model's outputs before deploying it to\\n\",\"  production.\\n\",\"\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"d0018f8f\",\"metadata\":{},\"source\":[\"## 13. (Optional) Quick Temporary Browser Preview\\n\",\"\\n\",\"Before setting up a *permanent* deployment, it's often useful to sanity-check\\n\",\"the model in a real browser UI first. `gradio`'s `share=True` option spins up\\n\",\"a temporary public URL directly from this Colab cell.\\n\",\"\\n\",\"**Note:** this link is temporary — it expires when this Colab runtime\\n\",\"disconnects/closes (typically within 72 hours, often sooner). For a\\n\",\"permanent link, continue to Section 14.\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"c2f38f99\",\"metadata\":{},\"outputs\":[],\"source\":[\"# Install Gradio (only needed once per runtime).\\n\",\"!pip install -q gradio\\n\",\"\\n\",\"import gradio as gr\\n\",\"\\n\",\"def chat_fn(message, history):\\n\",\"    \\\"\\\"\\\"Generates a reply from the fine-tuned model for the Gradio chat UI.\\\"\\\"\\\"\\n\",\"    prompt = f\\\"### Instruction:\\\\n{message}\\\\n\\\\n### Response:\\\\n\\\"\\n\",\"    result = generator(\\n\",\"        prompt,\\n\",\"        max_new_tokens=200,\\n\",\"        do_sample=True,\\n\",\"        temperature=0.7,\\n\",\"        top_p=0.9,\\n\",\"    )\\n\",\"    full_text = result[0][\\\"generated_text\\\"]\\n\",\"    # Strip the prompt back off so only the newly generated reply is shown.\\n\",\"    return full_text[len(prompt):].strip()\\n\",\"\\n\",\"# `share=True` tunnels this local Gradio server to a temporary public URL,\\n\",\"# printed below (e.g. https://xxxxxxxx.gradio.live). Click it to test in\\n\",\"# a real browser tab, on any device, while this Colab cell keeps running.\\n\",\"demo = gr.ChatInterface(fn=chat_fn, title=\\\"Knatware LLM — Live Preview (temporary link)\\\")\\n\",\"demo.launch(share=True)\"]},{\"cell_type\":\"markdown\",\"id\":\"d894dc30\",\"metadata\":{},\"source\":[\"## 14. Deploy Permanently to a Free Browser Host (Hugging Face Spaces)\\n\",\"\\n\",\"This section publishes your fine-tuned model to **Hugging Face Spaces**, a\\n\",\"free-tier hosting platform for ML demos. Unlike the temporary link in\\n\",\"Section 13, this gives you a **permanent URL** that keeps working after this\\n\",\"Colab notebook is closed, e.g.:\\n\",\"\\n\",\"```\\n\",\"https://huggingface.co/spaces/<your-username>/<your-space-name>\\n\",\"```\\n\",\"\\n\",\"### How it works\\n\",\"1. We merge the LoRA adapter into the base model (if not already done) so the\\n\",\"   Space doesn't need to juggle adapters at inference time.\\n\",\"2. We push that merged model to the Hugging Face **Hub** (model storage).\\n\",\"3. We generate an `app.py` (Gradio web app) and `requirements.txt`.\\n\",\"4. We create a Hugging Face **Space** (free `cpu-basic` tier by default) and\\n\",\"   upload those two files. Hugging Face automatically builds and hosts the\\n\",\"   app — no server management required on your side.\\n\",\"\\n\",\"### Prerequisites\\n\",\"- You must be logged in to the Hugging Face Hub (Section 2 — `login()` /\\n\",\"  `notebook_login()`), with a token that has **write** access.\\n\",\"- Your Hugging Face account, not just a token — Spaces are created under\\n\",\"  your username (or an organization you belong to).\"]},{\"cell_type\":\"markdown\",\"id\":\"5a2be4e0\",\"metadata\":{},\"source\":[\"### 14.1 Compulsory: deployment configuration\\n\",\"\\n\",\"Edit every value in the cell below before running the deployment cells.\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"280e223b\",\"metadata\":{},\"outputs\":[],\"source\":[\"# =============================================================================\\n\",\"# COMPULSORY DEPLOYMENT CONFIGURATION\\n\",\"# =============================================================================\\n\",\"\\n\",\"# COMPULSORY: your Hugging Face username or organization name.\\n\",\"# Find it at https://huggingface.co/settings/profile\\n\",\"HF_USERNAME = \\\"{{HF_USERNAME}}\\\"\\n\",\"\\n\",\"# COMPULSORY: a short, URL-safe name for your Space (letters, numbers, \\\"-\\\").\\n\",\"# The final demo will live at:\\n\",\"#   https://huggingface.co/spaces/<HF_USERNAME>/<SPACE_NAME>\\n\",\"SPACE_NAME = \\\"{{SPACE_NAME}}\\\"\\n\",\"\\n\",\"# COMPULSORY: Hub repo id where the MERGED (full, adapter-free) fine-tuned\\n\",\"# model will be uploaded. This is what the Space will download and serve.\\n\",\"DEPLOY_MODEL_REPO_ID = \\\"{{DEPLOY_MODEL_REPO_ID}}\\\"\\n\",\"\\n\",\"# COMPULSORY: Space hardware tier. \\\"cpu-basic\\\" is free forever but slower\\n\",\"# for generation (fine for small 1B-3B models / short demo replies).\\n\",\"# Paid tiers (e.g. \\\"t4-small\\\") are faster if you upgrade later.\\n\",\"SPACE_HARDWARE = \\\"{{SPACE_HARDWARE}}\\\"\\n\",\"\\n\",\"# COMPULSORY: whether the Space (and the model repo above) should be public.\\n\",\"# Set to False to keep them private (private Spaces require a paid tier to\\n\",\"# actually be *used* by others, but you can still view/run it yourself).\\n\",\"SPACE_PUBLIC = {{SPACE_PUBLIC}}\\n\",\"\\n\",\"print(\\\"Deployment configuration set:\\\")\\n\",\"print(f\\\"  HF_USERNAME           = {HF_USERNAME}\\\")\\n\",\"print(f\\\"  SPACE_NAME             = {SPACE_NAME}\\\")\\n\",\"print(f\\\"  DEPLOY_MODEL_REPO_ID   = {DEPLOY_MODEL_REPO_ID}\\\")\\n\",\"print(f\\\"  SPACE_HARDWARE         = {SPACE_HARDWARE}\\\")\\n\",\"print(f\\\"  SPACE_PUBLIC           = {SPACE_PUBLIC}\\\")\\n\",\"print(f\\\"  Final Space URL will be:\\\")\\n\",\"print(f\\\"    https://huggingface.co/spaces/{HF_USERNAME}/{SPACE_NAME}\\\")\"]},{\"cell_type\":\"markdown\",\"id\":\"19037460\",\"metadata\":{},\"source\":[\"### 14.2 Merge the LoRA adapter into the base model (if not already merged)\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"cfa6a2aa\",\"metadata\":{},\"outputs\":[],\"source\":[\"# If Section 9's optional merge step (MERGE_AND_SAVE) was already run, reuse\\n\",\"# that result. Otherwise merge now so we have a single, standalone model to\\n\",\"# deploy (no `peft` dependency needed inside the Space).\\n\",\"if \\\"merged_model\\\" not in globals():\\n\",\"    print(\\\"No merged model found in memory yet — merging LoRA adapter now...\\\")\\n\",\"    merged_model = trainer.model.merge_and_unload()\\n\",\"    merged_output_dir = OUTPUT_DIR + \\\"-merged\\\"\\n\",\"    merged_model.save_pretrained(merged_output_dir, safe_serialization=True)\\n\",\"    tokenizer.save_pretrained(merged_output_dir)\\n\",\"    print(f\\\"Merged model saved locally to: {merged_output_dir}\\\")\\n\",\"else:\\n\",\"    print(\\\"Reusing already-merged model from Section 9.\\\")\"]},{\"cell_type\":\"markdown\",\"id\":\"7e77635d\",\"metadata\":{},\"source\":[\"### 14.3 Push the merged model to the Hugging Face Hub\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"4f3f000b\",\"metadata\":{},\"outputs\":[],\"source\":[\"# Upload the merged, standalone model + tokenizer to the Hub. The Space\\n\",\"# (Section 14.5) will download it from here at startup.\\n\",\"merged_model.push_to_hub(DEPLOY_MODEL_REPO_ID, private=not SPACE_PUBLIC)\\n\",\"tokenizer.push_to_hub(DEPLOY_MODEL_REPO_ID, private=not SPACE_PUBLIC)\\n\",\"\\n\",\"print(f\\\"Merged model pushed to: https://huggingface.co/{DEPLOY_MODEL_REPO_ID}\\\")\"]},{\"cell_type\":\"markdown\",\"id\":\"62626855\",\"metadata\":{},\"source\":[\"### 14.4 Write the Gradio app (`app.py`) and `requirements.txt`\\n\",\"\\n\",\"These two files are all Hugging Face Spaces needs to build and serve your model.\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"ed4657cd\",\"metadata\":{},\"outputs\":[],\"source\":[\"%%writefile app.py\\n\",\"\\\"\\\"\\\"\\n\",\"Gradio web app for the Knatware fine-tuned LLM.\\n\",\"This file is uploaded to a Hugging Face Space and run there directly — it\\n\",\"does NOT run inside this Colab notebook. Hugging Face installs\\n\",\"`requirements.txt` and then executes this script automatically.\\n\",\"\\\"\\\"\\\"\\n\",\"\\n\",\"import os\\n\",\"import torch\\n\",\"import gradio as gr\\n\",\"from transformers import AutoModelForCausalLM, AutoTokenizer, pipeline\\n\",\"\\n\",\"# Model repo id is injected at deploy time (see Section 14.5) via an\\n\",\"# environment variable so this file doesn't need to be regenerated if you\\n\",\"# retrain and push a new model version under the same repo id.\\n\",\"MODEL_REPO_ID = os.environ.get(\\\"MODEL_REPO_ID\\\", \\\"REPLACE_WITH_YOUR_MODEL_REPO_ID\\\")\\n\",\"\\n\",\"print(f\\\"Loading model: {MODEL_REPO_ID}\\\")\\n\",\"\\n\",\"# Free-tier Spaces are CPU-only by default, so we fall back gracefully:\\n\",\"# GPU + bfloat16 if a GPU is available (e.g. on a paid Space), else CPU + float32.\\n\",\"device = \\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\"\\n\",\"dtype = torch.bfloat16 if device == \\\"cuda\\\" else torch.float32\\n\",\"\\n\",\"tokenizer = AutoTokenizer.from_pretrained(MODEL_REPO_ID)\\n\",\"if tokenizer.pad_token is None:\\n\",\"    tokenizer.pad_token = tokenizer.eos_token\\n\",\"\\n\",\"model = AutoModelForCausalLM.from_pretrained(\\n\",\"    MODEL_REPO_ID,\\n\",\"    torch_dtype=dtype,\\n\",\"    device_map=\\\"auto\\\" if device == \\\"cuda\\\" else None,\\n\",\")\\n\",\"if device == \\\"cpu\\\":\\n\",\"    model.to(device)\\n\",\"\\n\",\"generator = pipeline(\\\"text-generation\\\", model=model, tokenizer=tokenizer, device_map=\\\"auto\\\" if device == \\\"cuda\\\" else None)\\n\",\"\\n\",\"\\n\",\"def respond(message, history, max_new_tokens, temperature, top_p):\\n\",\"    \\\"\\\"\\\"Builds a prompt from the chat history and generates the next reply.\\\"\\\"\\\"\\n\",\"    prompt = f\\\"### Instruction:\\\\n{message}\\\\n\\\\n### Response:\\\\n\\\"\\n\",\"\\n\",\"    output = generator(\\n\",\"        prompt,\\n\",\"        max_new_tokens=max_new_tokens,\\n\",\"        do_sample=temperature > 0,\\n\",\"        temperature=max(temperature, 0.01),\\n\",\"        top_p=top_p,\\n\",\"        pad_token_id=tokenizer.pad_token_id,\\n\",\"    )\\n\",\"    full_text = output[0][\\\"generated_text\\\"]\\n\",\"    return full_text[len(prompt):].strip()\\n\",\"\\n\",\"\\n\",\"with gr.Blocks(title=\\\"Knatware LLM Demo\\\") as demo:\\n\",\"    gr.Markdown(\\n\",\"        f\\\"\\\"\\\"# 🔧 Knatware Fine-Tuned LLM\\n\",\"Live demo of a model fine-tuned with the Knatware LLM pipeline.\\n\",\"Model: `{MODEL_REPO_ID}`\\n\",\"\\n\",\"*Running on a free-tier CPU Space — replies may take a little while.*\\\"\\\"\\\"\\n\",\"    )\\n\",\"\\n\",\"    with gr.Accordion(\\\"Generation settings\\\", open=False):\\n\",\"        max_new_tokens = gr.Slider(16, 512, value=200, step=8, label=\\\"Max new tokens\\\")\\n\",\"        temperature = gr.Slider(0.0, 1.5, value=0.7, step=0.05, label=\\\"Temperature\\\")\\n\",\"        top_p = gr.Slider(0.1, 1.0, value=0.9, step=0.05, label=\\\"Top-p\\\")\\n\",\"\\n\",\"    chat = gr.ChatInterface(\\n\",\"        fn=respond,\\n\",\"        additional_inputs=[max_new_tokens, temperature, top_p],\\n\",\"    )\\n\",\"\\n\",\"if __name__ == \\\"__main__\\\":\\n\",\"    # Spaces expect the app to bind to 0.0.0.0:7860 by default; Gradio's\\n\",\"    # default launch() already does this correctly on Spaces.\\n\",\"    demo.launch()\\n\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"926035b7\",\"metadata\":{},\"outputs\":[],\"source\":[\"%%writefile requirements.txt\\n\",\"transformers>=4.44.0\\n\",\"torch>=2.2.0\\n\",\"gradio>=4.40.0\\n\",\"accelerate>=0.33.0\\n\",\"sentencepiece\\n\",\"safetensors\\n\"]},{\"cell_type\":\"markdown\",\"id\":\"a7f4ace9\",\"metadata\":{},\"source\":[\"### 14.5 Create the Space and upload the files\\n\",\"\\n\",\"This is the step that actually goes live — after it finishes, your permanent link is ready.\"]},{\"cell_type\":\"code\",\"execution_count\":null,\"id\":\"16c0e624\",\"metadata\":{},\"outputs\":[],\"source\":[\"from huggingface_hub import HfApi\\n\",\"\\n\",\"api = HfApi()\\n\",\"\\n\",\"# Create (or reuse, if it already exists) the Space repo.\\n\",\"space_repo_id = f\\\"{HF_USERNAME}/{SPACE_NAME}\\\"\\n\",\"\\n\",\"api.create_repo(\\n\",\"    repo_id=space_repo_id,\\n\",\"    repo_type=\\\"space\\\",\\n\",\"    space_sdk=\\\"gradio\\\",\\n\",\"    private=not SPACE_PUBLIC,\\n\",\"    exist_ok=True,          # safe to re-run; won't error if the Space exists\\n\",\")\\n\",\"\\n\",\"# Tell the Space (via a repo secret) which model to load, so app.py never\\n\",\"# has to be edited/re-uploaded again if you retrain and push a v2 model to\\n\",\"# the same DEPLOY_MODEL_REPO_ID.\\n\",\"api.add_space_secret(\\n\",\"    repo_id=space_repo_id,\\n\",\"    key=\\\"MODEL_REPO_ID\\\",\\n\",\"    value=DEPLOY_MODEL_REPO_ID,\\n\",\")\\n\",\"\\n\",\"# Upload the app + requirements. Hugging Face automatically detects the\\n\",\"# push, builds a container, installs requirements.txt, and starts app.py.\\n\",\"api.upload_file(\\n\",\"    path_or_fileobj=\\\"app.py\\\",\\n\",\"    path_in_repo=\\\"app.py\\\",\\n\",\"    repo_id=space_repo_id,\\n\",\"    repo_type=\\\"space\\\",\\n\",\")\\n\",\"api.upload_file(\\n\",\"    path_or_fileobj=\\\"requirements.txt\\\",\\n\",\"    path_in_repo=\\\"requirements.txt\\\",\\n\",\"    repo_id=space_repo_id,\\n\",\"    repo_type=\\\"space\\\",\\n\",\")\\n\",\"\\n\",\"space_url = f\\\"https://huggingface.co/spaces/{HF_USERNAME}/{SPACE_NAME}\\\"\\n\",\"print(\\\"Deployment files uploaded successfully.\\\")\\n\",\"print(f\\\"Your permanent demo link (build takes ~2-5 min the first time):\\\")\\n\",\"print(f\\\"  {space_url}\\\")\"]},{\"cell_type\":\"markdown\",\"id\":\"e856d078\",\"metadata\":{},\"source\":[\"### 14.6 Notes\\n\",\"\\n\",\"- **Build time:** the first deploy takes a few minutes while the Space\\n\",\"  installs `requirements.txt` and downloads the model — refresh the Space\\n\",\"  page to watch build logs.\\n\",\"- **Cold starts:** free `cpu-basic` Spaces sleep after inactivity and take a\\n\",\"  moment to wake back up on the next visit; this is expected on the free tier.\\n\",\"- **Updating the model:** to publish a retrained model, just re-run Sections\\n\",\"  9, 14.2 and 14.3 with the *same* `DEPLOY_MODEL_REPO_ID`, then push it again\\n\",\"  — the Space will pick up the new weights next time it restarts (no need to\\n\",\"  re-upload `app.py`).\\n\",\"- **Embedding elsewhere:** any Space can be embedded in another website via\\n\",\"  an `<iframe src=\\\"https://<username>-<space-name>.hf.space\\\">`.\\n\",\"- **Faster inference:** if replies feel slow, either upgrade `SPACE_HARDWARE`\\n\",\"  to a paid GPU tier in the Space's Settings tab, or convert the merged\\n\",\"  model to GGUF format and swap `app.py` to use `llama-cpp-python`, which\\n\",\"  runs quantized models efficiently on free CPU tiers.\"]},{\"cell_type\":\"markdown\",\"id\":\"knatware-footer\",\"metadata\":{},\"source\":[\"---\\n\",\"\\n\",\"© Knatware Technology — Notebook developed by Kayode Okosi, LLM Developer.\"]}],\"metadata\":{\"accelerator\":\"GPU\",\"colab\":{\"name\":\"Knatware_Technology_LLM_FineTuning_Notebook.ipynb\",\"provenance\":[]},\"kernelspec\":{\"display_name\":\"Python 3\",\"name\":\"python3\"},\"language_info\":{\"name\":\"python\"}},\"nbformat\":4,\"nbformat_minor\":5}";
// --- helpers to turn a form value into a valid Python literal, safely
//     embedded inside the notebook's own already-serialized JSON text ------

function pyString(v, fallback) {
  const s = (v === undefined || v === null || v === "") ? fallback : String(v);
  const pythonSourceText = JSON.stringify(s).slice(1, -1);
  return JSON.stringify(pythonSourceText).slice(1, -1);
}

function pyNumber(v, fallback) {
  const n = (v === undefined || v === null || v === "") ? fallback : v;
  return String(n);
}

function pyBool(v, fallback) {
  const s = (v === undefined || v === null || v === "") ? fallback : String(v);
  return (s === "Yes" || s === "true" || s === "True" || s === true) ? "True" : "False";
}

function pyList(v, fallback) {
  const raw = (v === undefined || v === null || v === "") ? fallback : String(v);
  const items = raw.split(",").map(s => s.trim()).filter(Boolean);
  const listLiteral = "[" + items.map(i => `"${i}"`).join(", ") + "]";
  return JSON.stringify(listLiteral).slice(1, -1);
}

// --- resolve every field, preferring Page 4's answer, then the HF-derived
//     recommendation, then a hardcoded sane default -------------------------

const HF_USERNAME = pyString(page4.HF_USERNAME, rec.recommendedHubRepoId ? rec.recommendedHubRepoId.split("/")[0] : "your-username");
const SPACE_NAME_raw = page4.SPACE_NAME || rec.recommendedSpaceName || "knatware-llm-demo";
const DEPLOY_MODEL_REPO_ID_raw = page4.DEPLOY_MODEL_REPO_ID || rec.recommendedDeployRepoId
  || `${page4.HF_USERNAME || "your-username"}/knatware-finetuned-model-merged`;

const replacements = {
  MODEL_NAME:                     pyString(rec.MODEL_NAME, "Qwen/Qwen2.5-1.5B-Instruct"),
  DATASET_NAME:                   pyString(rec.DATASET_NAME, "mlabonne/guanaco-llama2-1k"),
  DATASET_SPLIT:                  pyString(page4.DATASET_SPLIT, rec.recommendedDatasetSplit || "train"),
  DATASET_TEXT_FIELD:             pyString(page4.DATASET_TEXT_FIELD, rec.recommendedDatasetTextField || "text"),
  OUTPUT_DIR:                     pyString(page4.OUTPUT_DIR, "./knatware-finetuned-model"),
  MAX_SEQ_LENGTH:                 pyNumber(page4.MAX_SEQ_LENGTH, rec.recommendedMaxSeqLength || 1024),
  USE_4BIT:                       pyBool(page4.USE_4BIT, rec.recommendedUse4bit || "Yes"),

  LORA_R:                         pyNumber(page4.LORA_R, 16),
  LORA_ALPHA:                     pyNumber(page4.LORA_ALPHA, 32),
  LORA_DROPOUT:                   pyNumber(page4.LORA_DROPOUT, 0.05),
  LORA_TARGET_MODULES:            pyList(page4.LORA_TARGET_MODULES, rec.recommendedLoraTargets || "q_proj,k_proj,v_proj,o_proj"),

  NUM_TRAIN_EPOCHS:               pyNumber(page4.NUM_TRAIN_EPOCHS, 3),
  PER_DEVICE_TRAIN_BATCH_SIZE:    pyNumber(page4.PER_DEVICE_TRAIN_BATCH_SIZE, 2),
  GRADIENT_ACCUMULATION_STEPS:    pyNumber(page4.GRADIENT_ACCUMULATION_STEPS, 4),
  LEARNING_RATE:                  pyNumber(page4.LEARNING_RATE, "2e-4"),
  LR_SCHEDULER_TYPE:              pyString(page4.LR_SCHEDULER_TYPE, "cosine"),

  MERGE_AND_SAVE:                 pyBool(page4.MERGE_AND_SAVE, "No"),
  PUSH_TO_HUB:                    pyBool(page4.PUSH_TO_HUB, "No"),
  HUB_REPO_ID:                    pyString(page4.HUB_REPO_ID, rec.recommendedHubRepoId || "your-username/knatware-finetuned-model"),

  TEST_PROMPT:                    pyString(page4.TEST_PROMPT,
                                     "### Instruction:\nExplain what fine-tuning an LLM means in one paragraph.\n\n### Response:\n"),
  TEST_MAX_NEW_TOKENS:            pyNumber(page4.TEST_MAX_NEW_TOKENS, 200),
  TEST_TEMPERATURE:               pyNumber(page4.TEST_TEMPERATURE, 0.7),
  TEST_TOP_P:                     pyNumber(page4.TEST_TOP_P, 0.9),

  HF_USERNAME:                    HF_USERNAME,
  SPACE_NAME:                     pyString(SPACE_NAME_raw, SPACE_NAME_raw),
  DEPLOY_MODEL_REPO_ID:           pyString(DEPLOY_MODEL_REPO_ID_raw, DEPLOY_MODEL_REPO_ID_raw),
  SPACE_HARDWARE:                 pyString(page4.SPACE_HARDWARE, "cpu-basic"),
  SPACE_PUBLIC:                   pyBool(page4.SPACE_PUBLIC, "Yes"),

  // Sourced from the "Config (edit token here)" node near the start of the
  // workflow — that's the one place to paste a Hugging Face token.
  HF_TOKEN:                       pyString(hfToken, ""),
};

// --- apply every replacement ------------------------------------------------

let notebookText = TEMPLATE;
for (const [key, value] of Object.entries(replacements)) {
  const token = new RegExp(`\\{\\{${key}\\}\\}`, "g");
  notebookText = notebookText.replace(token, value);
}

const leftover = notebookText.match(/\{\{[A-Z0-9_]+\}\}/g);
if (leftover) {
  throw new Error("Unfilled placeholders remain: " + [...new Set(leftover)].join(", ") +
    " — this means a token in the notebook template has no matching key in the replacements object above (or vice versa). Check spelling/casing on both sides.");
}

// Self-test: make sure we produced valid, parseable notebook JSON before
// handing it off — catches any templating corruption immediately instead of
// silently shipping a broken .ipynb.
try {
  const parsedCheck = JSON.parse(notebookText);
  if (!Array.isArray(parsedCheck.cells) || parsedCheck.cells.length === 0) {
    throw new Error("parsed notebook has no cells");
  }
} catch (e) {
  throw new Error("Generated notebook failed to validate as JSON: " + e.message +
    " — this points to a bug in the template-filling step, not your form answers.");
}

// --- package as a downloadable binary file, carrying the delivery choice
//     forward for the "Delivery Method?" IF node ----------------------------

const fileName = (page4.NOTEBOOK_FILENAME && page4.NOTEBOOK_FILENAME.trim())
  ? page4.NOTEBOOK_FILENAME.trim()
  : "Knatware_LLM_FineTuning_Generated.ipynb";

const base64 = Buffer.from(notebookText, "utf-8").toString("base64");

const deliverToDrive = (page4.DELIVERY_METHOD || "").startsWith("Upload to Google Drive");

return [
  {
    json: {
      fileName,
      byteLength: Buffer.byteLength(notebookText, "utf-8"),
      deliverToDrive,
      driveFolderId: (page4.DRIVE_FOLDER_ID || "").trim(),
    },
    binary: {
      data: {
        data: base64,
        mimeType: "application/x-ipynb+json",
        fileName: fileName,
      },
    },
  },
];

// ---------------------------------------------------------------------------
// Build Colab Link
// ---------------------------------------------------------------------------
// Google Drive's upload response includes the new file's id — Colab can
// open any Drive-hosted .ipynb directly at this URL pattern.
// ---------------------------------------------------------------------------

const driveFile = $input.first().json;
const fileId = driveFile.id;

if (!fileId) {
  throw new Error("Google Drive upload did not return a file id — check the Drive node's credentials/response.");
}

const colabUrl = `https://colab.research.google.com/drive/${fileId}`;

return [
  {
    json: {
      fileId,
      colabUrl,
      fileName: driveFile.name || "notebook.ipynb",
    },
  },
];

